SCRATCH="/private/tmp/claude-501/-Users-techiee--claude-spares-spare-vX7DkF/8ea4555c-def4-4a5c-ac6d-e44a2117054c/scratchpad"
cat > "$SCRATCH/probe.py" <<'EOF'
import json,re,html,urllib.request,time
UA={"User-Agent":"InterviewPrototype admin@example.com"}
def get(u):
    return urllib.request.urlopen(urllib.request.Request(u,headers=UA),timeout=40).read()
m=json.loads(get("https://www.sec.gov/files/company_tickers.json"))
T={v["ticker"]:v for v in m.values()}
for t in ["BRK-B","BRK.B","SPY","ASML","QQQ"]:
    print("map",t,"->",T.get(t,{}).get("cik_str","NOT IN MAP"))
def clean(b):
    t=b.decode("utf8","ignore")
    t=re.sub(r'<(script|style|ix:header)[\s\S]*?</\1>',' ',t,flags=re.I)
    t=html.unescape(re.sub(r'<[^>]+>',' ',t)); return re.sub(r'\s+',' ',t)
STARTS={"1A":r'item\s*1a\.?\W{0,5}risk\s+factors',"7":r'item\s*7\.?\W{0,5}management.{0,3}s\s+discussion'}
ENDS={"1A":r'item\s*(1b|1c|2)\.?\W{0,5}(unresolved|cybersecurity|properties)',"7":r'item\s*(7a|8)\.?\W{0,5}(quantitative|financial\s+statements)'}
for t in ["AAPL","NVDA","XOM","JPM","MSFT","BAC","ASML"]:
    cik=T[t]["cik_str"]; time.sleep(.2)
    r=json.loads(get(f"https://data.sec.gov/submissions/CIK{cik:010d}.json"))["filings"]["recent"]
    latest={}
    for f,a,d,p in zip(r["form"],r["accessionNumber"],r["filingDate"],r["primaryDocument"]):
        latest.setdefault(f,(a,d,p))
    print(f"\n{t}: 10-K {latest.get('10-K',('',''))[1]}  10-Q {latest.get('10-Q',('',''))[1]}  20-F {latest.get('20-F',('',''))[1]}")
    if '10-K' not in latest: continue
    a,_,p=latest['10-K']; time.sleep(.2)
    x=clean(get(f"https://www.sec.gov/Archives/edgar/data/{cik}/{a.replace('-','')}/{p}"))
    print(" chars",len(x),"~tokens",len(x)//4)
    for k in STARTS:
        st=[s.start() for s in re.finditer(STARTS[k],x,flags=re.I)]
        spans=[]
        for s in st:
            e=re.search(ENDS[k],x[s+20:],flags=re.I)
            spans.append(((e.start()+20) if e else -1))
        last=spans[-1] if spans else None
        print(f" item {k}: starts={len(st)} span_chars={spans[:8]} last_match_span={last} best={max(spans) if spans else None}")
    print(" bare 'Item 1A' count",len(re.findall(r'item\s*1a',x,flags=re.I)))
EOF
python3 -I "$SCRATCH/probe.py"

