import type { Briefing, BriefingFailure, ProgressEvent } from './types'

export interface BriefingHandlers {
  onProgress: (event: ProgressEvent) => void
  onResult: (briefing: Briefing) => void
  onFailed: (failure: BriefingFailure) => void
}

/**
 * Streams one briefing, and returns a function that stops listening.
 *
 * It must close on every final event. EventSource reconnects by itself when a stream
 * ends, which would generate the briefing again and pay for it twice.
 */
export function streamBriefing(
  ticker: string,
  useBackupLlm: boolean,
  handlers: BriefingHandlers,
): () => void {
  const query = useBackupLlm ? '?force_failover=true' : ''
  const source = new EventSource(`/api/briefings/${encodeURIComponent(ticker)}/stream${query}`)

  source.addEventListener('progress', (event) => {
    handlers.onProgress(JSON.parse(event.data))
  })
  source.addEventListener('result', (event) => {
    source.close()
    handlers.onResult(JSON.parse(event.data))
  })
  source.addEventListener('failed', (event) => {
    source.close()
    handlers.onFailed(JSON.parse(event.data))
  })
  // The browser's own connection event, separate from our `failed` event.
  source.onerror = () => {
    source.close()
    handlers.onFailed({
      code: 'connection_error',
      message: "The briefing service can't be reached. Check that the backend is running.",
      retryable: true,
    })
  }
  return () => source.close()
}

const NOT_AVAILABLE = '—'

export function formatPrice(value: number | null | undefined, currency = 'USD'): string {
  if (value == null) return NOT_AVAILABLE
  return new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(value)
}

/** Large amounts such as $478.8B. */
export function formatCompact(value: number | null | undefined, currency = 'USD'): string {
  if (value == null) return NOT_AVAILABLE
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency,
    notation: 'compact',
    minimumFractionDigits: 1,
    maximumFractionDigits: 1,
  }).format(value)
}

export function formatSigned(value: number | null | undefined, currency = 'USD'): string {
  if (value == null) return NOT_AVAILABLE
  return `${value >= 0 ? '+' : '−'}${formatPrice(Math.abs(value), currency)}`
}

export function formatPercent(value: number | null | undefined): string {
  if (value == null) return NOT_AVAILABLE
  return `${value >= 0 ? '+' : '−'}${Math.abs(value).toFixed(2)}%`
}

export function formatRange(
  low: number | null | undefined,
  high: number | null | undefined,
  currency = 'USD',
): string {
  if (low == null || high == null) return NOT_AVAILABLE
  return `${formatPrice(low, currency)} – ${formatPrice(high, currency)}`
}

/** Dates from filings have no time zone, so read them as written. */
export function formatDate(isoDate: string | null | undefined): string {
  if (!isoDate) return NOT_AVAILABLE
  return new Date(`${isoDate.slice(0, 10)}T00:00:00Z`).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    timeZone: 'UTC',
  })
}

export function formatDateTime(isoDateTime: string | null | undefined): string {
  if (!isoDateTime) return NOT_AVAILABLE
  return new Date(isoDateTime).toLocaleString('en-US', {
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
    timeZoneName: 'short',
  })
}

import { Search } from 'lucide-react'
import { useState, type FormEvent } from 'react'

interface Props {
  busy: boolean
  onSubmit: (ticker: string) => void
}

export function TickerSearch({ busy, onSubmit }: Props) {
  const [value, setValue] = useState('')

  function handleSubmit(event: FormEvent) {
    event.preventDefault()
    const ticker = value.trim().toUpperCase()
    if (ticker && !busy) onSubmit(ticker)
  }

  return (
    <form onSubmit={handleSubmit} role="search" className="flex w-full max-w-md gap-2">
      <label htmlFor="ticker" className="sr-only">
        Stock ticker
      </label>
      <div className="relative flex-1">
        <Search aria-hidden className="absolute top-2.5 left-3 size-4 text-slate-400" />
        <input
          id="ticker"
          value={value}
          onChange={(event) => setValue(event.target.value)}
          placeholder="Enter a ticker, such as AAPL"
          maxLength={12}
          autoComplete="off"
          spellCheck={false}
          className="h-9 w-full rounded-md border border-slate-300 bg-white pr-3 pl-9 text-sm uppercase placeholder:text-slate-400 placeholder:normal-case"
        />
      </div>
      <button
        type="submit"
        disabled={busy || !value.trim()}
        className="h-9 rounded-md bg-blue-700 px-4 text-sm font-medium text-white hover:bg-blue-800 disabled:cursor-not-allowed disabled:bg-slate-300"
      >
        {busy ? 'Working…' : 'Get briefing'}
      </button>
    </form>
  )
}

import { Check, Circle, LoaderCircle } from 'lucide-react'

const STEPS = [
  ['company', 'Find the company and its filings'],
  ['quote', 'Get the current quote'],
  ['financials', 'Read annual financials'],
  ['filings', 'Read the latest SEC filings'],
  ['analysis', 'Summarize the filings'],
  ['verification', 'Check each quote against the filings'],
] as const

export function ProgressSteps({ ticker, current }: { ticker: string; current: string | null }) {
  const currentIndex = STEPS.findIndex(([step]) => step === current)
  return (
    <section
      aria-live="polite"
      aria-label={`Building the briefing for ${ticker}`}
      className="mx-auto mt-10 max-w-md rounded-lg border border-slate-200 bg-white p-6"
    >
      <h2 className="font-semibold">Building the {ticker} briefing</h2>
      <p className="mt-1 text-sm text-slate-500">A new briefing usually takes under a minute.</p>
      <ol className="mt-5 space-y-3">
        {STEPS.map(([step, label], index) => {
          const done = index < currentIndex
          const active = index === currentIndex
          return (
            <li key={step} className="flex items-center gap-3 text-sm">
              {done && <Check aria-hidden className="size-4 text-emerald-700" />}
              {active && <LoaderCircle aria-hidden className="size-4 animate-spin text-blue-700" />}
              {!done && !active && <Circle aria-hidden className="size-4 text-slate-300" />}
              <span className={active ? 'font-medium' : done ? 'text-slate-700' : 'text-slate-400'}>
                {label}
                <span className="sr-only">{done ? ' (done)' : active ? ' (in progress)' : ''}</span>
              </span>
            </li>
          )
        })}
      </ol>
    </section>
  )
}

import { ArrowDownRight, ArrowUpRight } from 'lucide-react'
import type { Company, Quote } from '../api/types'
import {
  formatCompact,
  formatDateTime,
  formatPercent,
  formatPrice,
  formatRange,
  formatSigned,
} from '../lib/format'

function Metric({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-lg border border-slate-200 bg-white px-4 py-3">
      <dt className="text-xs text-slate-500">{label}</dt>
      <dd className="mt-1 text-sm font-medium tabular-nums">{value}</dd>
    </div>
  )
}

export function QuoteHeader({ company, quote }: { company: Company; quote: Quote | null }) {
  const currency = quote?.currency ?? 'USD'
  const rising = (quote?.change ?? 0) >= 0
  const ChangeIcon = rising ? ArrowUpRight : ArrowDownRight

  return (
    <header>
      <div className="flex flex-wrap items-end justify-between gap-x-8 gap-y-3">
        <div>
          <h2 className="text-2xl font-semibold tracking-tight">{company.name}</h2>
          <p className="mt-0.5 text-sm text-slate-500">
            {company.ticker}
            {quote?.exchange ? ` · ${quote.exchange}` : ''}
          </p>
        </div>
        {quote ? (
          <div className="text-right">
            <p className="text-3xl font-semibold tracking-tight tabular-nums">
              {formatPrice(quote.price, currency)}
            </p>
            {quote.change != null && (
              <p
                className={`mt-0.5 flex items-center justify-end gap-1 text-sm font-medium tabular-nums ${
                  rising ? 'text-emerald-700' : 'text-red-700'
                }`}
              >
                <ChangeIcon aria-hidden className="size-4" />
                {formatSigned(quote.change, currency)} ({formatPercent(quote.change_percent)})
              </p>
            )}
            <p className="mt-0.5 text-xs text-slate-500">
              {quote.is_saved ? 'Saved quote from ' : 'As of '}
              {formatDateTime(quote.as_of)}
            </p>
          </div>
        ) : (
          <p className="text-sm text-slate-500">Quote unavailable</p>
        )}
      </div>
      {quote && (
        <dl className="mt-4 grid grid-cols-2 gap-3 lg:grid-cols-4">
          <Metric label="Previous close" value={formatPrice(quote.previous_close, currency)} />
          <Metric label="Day range" value={formatRange(quote.day_low, quote.day_high, currency)} />
          <Metric label="52-week range" value={formatRange(quote.year_low, quote.year_high, currency)} />
          <Metric label="Market cap" value={formatCompact(quote.market_cap, currency)} />
        </dl>
      )}
    </header>
  )
}

import type { Financials } from '../api/types'
import { formatCompact, formatDate, formatPrice } from '../lib/format'

export function FinancialTable({ financials }: { financials: Financials }) {
  const { years, currency } = financials
  if (years.length === 0) return null
  // Oldest to newest, the way a trend reads.
  const ordered = [...years].reverse()
  const rows = [
    ['Revenue', (y: (typeof years)[number]) => formatCompact(y.revenue, currency)],
    ['Net income', (y: (typeof years)[number]) => formatCompact(y.net_income, currency)],
    ['Diluted EPS', (y: (typeof years)[number]) => formatPrice(y.eps_diluted, currency)],
  ] as const

  return (
    <section className="rounded-lg border border-slate-200 bg-white p-5">
      <h3 className="font-semibold">Annual financials</h3>
      <p className="mt-0.5 text-xs text-slate-500">Reported figures from SEC data, not generated by AI.</p>
      <div className="mt-3 overflow-x-auto">
        <table className="w-full min-w-[32rem] text-sm tabular-nums">
          <thead>
            <tr className="border-b border-slate-200 text-xs text-slate-500">
              <th scope="col" className="py-2 pr-4 text-left font-medium">
                Fiscal year ended
              </th>
              {ordered.map((year) => (
                <th key={year.period_end} scope="col" className="py-2 pl-4 text-right font-medium">
                  {formatDate(year.period_end)}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map(([label, value]) => (
              <tr key={label} className="border-b border-slate-100 last:border-0">
                <th scope="row" className="py-2 pr-4 text-left font-medium">
                  {label}
                </th>
                {ordered.map((year) => (
                  <td key={year.period_end} className="py-2 pl-4 text-right">
                    {value(year)}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {financials.warnings.map((warning) => (
        <p key={warning} className="mt-2 text-xs text-amber-800">
          {warning}
        </p>
      ))}
    </section>
  )
}

import { CircleAlert, CircleCheck, ExternalLink } from 'lucide-react'
import type { BriefingSection, Claim } from '../api/types'

const UNVERIFIED_LABEL = {
  quote_not_found: 'Quote not found in the filings',
  figures_not_in_quote: 'Figures not in the quote',
} as const

function ClaimItem({ claim }: { claim: Claim }) {
  const verified = claim.status === 'verified'
  return (
    <li className="py-3 first:pt-0 last:pb-0">
      <p className="text-sm leading-6">{claim.text}</p>
      <details className="group mt-1" open={!verified}>
        <summary className="inline-flex cursor-pointer items-center gap-1.5 text-xs font-medium">
          {verified ? (
            <span className="inline-flex items-center gap-1 text-emerald-800">
              <CircleCheck aria-hidden className="size-3.5" />
              Quote verified
            </span>
          ) : (
            <span className="inline-flex items-center gap-1 text-amber-800">
              <CircleAlert aria-hidden className="size-3.5" />
              {UNVERIFIED_LABEL[claim.status]}
            </span>
          )}
          <span className="font-normal text-slate-500 group-open:hidden">· Show quote</span>
        </summary>
        <blockquote
          className={`mt-2 border-l-2 pl-3 text-xs leading-5 text-slate-600 ${
            verified ? 'border-slate-300' : 'border-amber-400'
          }`}
        >
          {claim.supporting_quote}
        </blockquote>
      </details>
    </li>
  )
}

export function SectionCard({ section }: { section: BriefingSection }) {
  return (
    <section className="rounded-lg border border-slate-200 bg-white p-5">
      <div className="flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1">
        <h3 className="font-semibold">{section.title}</h3>
        <a
          href={section.filing_url}
          target="_blank"
          rel="noreferrer"
          className="inline-flex items-center gap-1 text-xs font-medium text-blue-700 hover:underline"
        >
          Open {section.filing_form}
          <ExternalLink aria-hidden className="size-3" />
          <span className="sr-only">(opens in a new tab)</span>
        </a>
      </div>
      {section.truncated && (
        <p className="mt-1 text-xs text-slate-500">
          This section is long, so the summary is based on its opening part.
        </p>
      )}
      {section.warning && <p className="mt-1 text-xs text-amber-800">{section.warning}</p>}
      {section.claims.length > 0 && (
        <ul className="mt-3 divide-y divide-slate-100">
          {section.claims.map((claim) => (
            <ClaimItem key={claim.text} claim={claim} />
          ))}
        </ul>
      )}
    </section>
  )
}

import { TriangleAlert } from 'lucide-react'
import type { Briefing, Filing } from '../api/types'
import { formatDate, formatDateTime } from '../lib/format'
import { FinancialTable } from './FinancialTable'
import { QuoteHeader } from './QuoteHeader'
import { SectionCard } from './SectionCard'

function FilingLink({ filing }: { filing: Filing }) {
  return (
    <li>
      <a href={filing.url} target="_blank" rel="noreferrer" className="font-medium text-blue-700 hover:underline">
        Form {filing.form}
      </a>
      <span className="text-slate-500"> · filed {formatDate(filing.filing_date)}</span>
    </li>
  )
}

const PROVIDER_NAME = { gemini: 'Gemini', groq: 'Groq' }

export function BriefingView({ briefing }: { briefing: Briefing }) {
  const { verification, llm } = briefing
  const sections = briefing.sections.filter((s) => s.claims.length > 0 || s.warning)

  return (
    <div className="mt-6 space-y-5">
      {briefing.warnings.length > 0 && (
        <div role="status" className="space-y-1 rounded-lg border border-amber-300 bg-amber-50 p-4 text-sm text-amber-900">
          {briefing.warnings.map((warning) => (
            <p key={warning} className="flex gap-2">
              <TriangleAlert aria-hidden className="mt-0.5 size-4 shrink-0" />
              {warning}
            </p>
          ))}
        </div>
      )}

      <QuoteHeader company={briefing.company} quote={briefing.quote} />

      <div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_20rem]">
        <div className="min-w-0 space-y-5">
          <FinancialTable financials={briefing.financials} />
          {sections.map((section) => (
            <SectionCard key={section.key} section={section} />
          ))}
        </div>

        <aside className="space-y-5">
          {verification.total_claims > 0 && (
            <section className="rounded-lg border border-slate-200 bg-white p-5">
              <h3 className="font-semibold">Trust check</h3>
              <p className="mt-2 text-2xl font-semibold tabular-nums">
                {verification.verified_claims} of {verification.total_claims}
              </p>
              <p className="text-sm text-slate-600">summary quotes found word for word in the filings read</p>
              <p className="mt-2 text-xs leading-5 text-slate-500">
                This confirms each quote is real and contains the point's figures. Review the quote to judge
                whether the summary is a fair reading.
              </p>
            </section>
          )}

          {briefing.client_questions.length > 0 && (
            <section className="rounded-lg border border-slate-200 bg-white p-5">
              <h3 className="font-semibold">Questions a client may ask</h3>
              <ul className="mt-2 list-disc space-y-2 pl-4 text-sm leading-6">
                {briefing.client_questions.map((question) => (
                  <li key={question}>{question}</li>
                ))}
              </ul>
            </section>
          )}

          <section className="rounded-lg border border-slate-200 bg-white p-5 text-sm">
            <h3 className="font-semibold">Sources</h3>
            <ul className="mt-2 space-y-1">
              {briefing.annual_filing && <FilingLink filing={briefing.annual_filing} />}
              {briefing.quarterly_filing && <FilingLink filing={briefing.quarterly_filing} />}
            </ul>
            {briefing.annual_filing && !briefing.quarterly_filing && (
              <p className="mt-2 text-xs text-slate-500">The 10-K is the newest report on file.</p>
            )}
            <p className="mt-3 text-xs leading-5 text-slate-500">
              {llm && (
                <>
                  Summarized by {PROVIDER_NAME[llm.provider]} ({llm.model})
                  {llm.from_saved ? ', saved from an earlier run' : ''}.{' '}
                </>
              )}
              Generated {formatDateTime(briefing.generated_at)}.
            </p>
          </section>
        </aside>
      </div>
    </div>
  )
}

import { CircleAlert } from 'lucide-react'
import { useRef, useState } from 'react'
import { streamBriefing } from './api/client'
import type { Briefing, BriefingFailure } from './api/types'
import { BriefingView } from './components/BriefingView'
import { ProgressSteps } from './components/ProgressSteps'
import { TickerSearch } from './components/TickerSearch'

const SUGGESTIONS = ['AAPL', 'MSFT', 'NVDA', 'JPM', 'XOM']

type State =
  | { status: 'idle' }
  | { status: 'loading'; ticker: string; step: string | null }
  | { status: 'done'; briefing: Briefing }
  | { status: 'failed'; ticker: string; failure: BriefingFailure }

export default function App() {
  const [state, setState] = useState<State>({ status: 'idle' })
  const [useBackupLlm, setUseBackupLlm] = useState(false)
  const stopStream = useRef<(() => void) | null>(null)

  // Started from user actions, not an effect, so React's Strict Mode can't run it twice.
  function start(ticker: string) {
    stopStream.current?.()
    setState({ status: 'loading', ticker, step: null })
    stopStream.current = streamBriefing(ticker, useBackupLlm, {
      onProgress: ({ step }) => setState({ status: 'loading', ticker, step }),
      onResult: (briefing) => setState({ status: 'done', briefing }),
      onFailed: (failure) => setState({ status: 'failed', ticker, failure }),
    })
  }

  return (
    <div className="flex min-h-screen flex-col">
      <div className="border-b border-slate-200 bg-white">
        <div className="mx-auto flex max-w-6xl flex-wrap items-center justify-between gap-x-8 gap-y-3 px-4 py-3 sm:px-6">
          <h1 className="font-semibold tracking-tight">Stock Briefing Assistant</h1>
          <TickerSearch busy={state.status === 'loading'} onSubmit={start} />
        </div>
      </div>

      <main className="mx-auto w-full max-w-6xl flex-1 px-4 pb-10 sm:px-6">
        {state.status === 'idle' && (
          <div className="mx-auto mt-16 max-w-xl text-center">
            <h2 className="text-2xl font-semibold tracking-tight">Get up to speed on a stock</h2>
            <p className="mt-2 text-slate-600">
              Current quote, reported financials and a summary of recent SEC filings, with every point
              checked against its source.
            </p>
            <div className="mt-5 flex flex-wrap justify-center gap-2">
              {SUGGESTIONS.map((ticker) => (
                <button
                  key={ticker}
                  type="button"
                  onClick={() => start(ticker)}
                  className="rounded-md border border-slate-300 bg-white px-3 py-1.5 text-sm font-medium hover:bg-slate-100"
                >
                  {ticker}
                </button>
              ))}
            </div>
          </div>
        )}

        {state.status === 'loading' && <ProgressSteps ticker={state.ticker} current={state.step} />}

        {state.status === 'failed' && (
          <div role="alert" className="mx-auto mt-10 max-w-lg rounded-lg border border-red-200 bg-white p-6">
            <h2 className="flex items-center gap-2 font-semibold text-red-800">
              <CircleAlert aria-hidden className="size-5" />
              No briefing for {state.ticker}
            </h2>
            <p className="mt-2 text-sm leading-6 text-slate-700">{state.failure.message}</p>
            {state.failure.retryable && (
              <button
                type="button"
                onClick={() => start(state.ticker)}
                className="mt-4 rounded-md bg-blue-700 px-4 py-2 text-sm font-medium text-white hover:bg-blue-800"
              >
                Try again
              </button>
            )}
          </div>
        )}

        {state.status === 'done' && <BriefingView briefing={state.briefing} />}
      </main>

      <footer className="border-t border-slate-200 bg-white">
        <div className="mx-auto flex max-w-6xl flex-wrap items-center justify-between gap-x-6 gap-y-2 px-4 py-3 text-xs text-slate-500 sm:px-6">
          <p>Information only, not investment advice. Sources: SEC EDGAR and Yahoo Finance (may be delayed).</p>
          <label className="flex cursor-pointer items-center gap-1.5">
            <input
              type="checkbox"
              checked={useBackupLlm}
              onChange={(event) => setUseBackupLlm(event.target.checked)}
            />
            Use backup LLM (Groq)
          </label>
        </div>
      </footer>
    </div>
  )
}

