const path = require("path");
const pptxgen = require("pptxgenjs");
const { applyTheme } = require(process.argv[3]);

const THEME = {
  name: "Trusted Briefing",
  headFontFace: "Cambria",
  bodyFontFace: "Calibri",
  colors: {
    dk1: "14292E", lt1: "FFFFFF", dk2: "0F4C4A", lt2: "EAF3F2",
    accent1: "0F6E68", accent2: "B45F06", accent3: "FBF1E3", accent4: "5B6B70",
    accent5: "CFE3E1", accent6: "14292E", hlink: "0F6E68", folHlink: "5B6B70",
  },
};

(async () => {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_WIDE"; // 13.33 x 7.5 inches
  pres.title = "Stock Briefing Assistant";
  pres.theme = { headFontFace: THEME.headFontFace, bodyFontFace: THEME.bodyFontFace };
  const C = pres.SchemeColor;

  pres.defineSlideMaster({
    title: "PITCH",
    background: { color: C.background1 },
    objects: [{
      placeholder: {
        options: { name: "title", type: "title", x: 0.5, y: 0.3, w: 12.33, h: 0.7, fontSize: 36, bold: true, color: C.text2, margin: 0, valign: "middle" },
        text: "Title",
      },
    }],
  });

  pres.addSection({ title: "Pitch" });
  const s = pres.addSlide({ masterName: "PITCH", sectionTitle: "Pitch" });
  s.addText("From ticker to a trusted stock briefing in under a minute", { placeholder: "title" });

  s.addText("For wealth advisors: live quote, reported financials and SEC filing summaries, with every summary point checked against its source.", {
    x: 0.5, y: 1.0, w: 12.33, h: 0.35, fontSize: 16, color: C.text1, margin: 0, isTextBox: true, objectName: "Subtitle",
  });

  // Measured results
  const stats = [
    ["95%", "of quotes verified on Gemini", "150 of 158, across 10 companies"],
    ["91%", "verified on the Groq backup", "31 of 34, across 3 companies"],
    ["16–47 s", "for a first-run briefing", "Saved briefings load in about 2 s"],
    ["30 of 30", "required 10-K sections found", "Banks and reorganized filers included"],
  ];
  const statW = 2.93, statGap = 0.2;
  stats.forEach(([big, label, detail], i) => {
    const x = 0.5 + i * (statW + statGap);
    s.addShape(pres.ShapeType.roundRect, { x, y: 1.5, w: statW, h: 1.2, rectRadius: 0.08, fill: { color: C.background2 }, line: { type: "none" }, objectName: `Result card ${i + 1}` });
    s.addText(big, { x: x + 0.15, y: 1.54, w: statW - 0.3, h: 0.52, fontSize: 28, bold: true, fontFace: "Cambria", color: C.accent1, margin: 0, isTextBox: true, objectName: `Result ${i + 1}` });
    s.addText([
      { text: label, options: { fontSize: 14, bold: true, color: C.text1, breakLine: true } },
      { text: detail, options: { fontSize: 12, color: C.accent4 } },
    ], { x: x + 0.15, y: 2.06, w: statW - 0.3, h: 0.58, margin: 0, valign: "top", isTextBox: true, objectName: `Result ${i + 1} detail` });
  });

  // How it works
  const steps = ["Enter a ticker", "Fetch live data\nYahoo, SEC EDGAR", "Summarize filings\nGemini, Groq backup", "Code checks quotes\nand figures", "Briefing with sources,\nthen ask follow-ups"];
  const stepW = 2.22, arrowW = 0.307;
  steps.forEach((step, i) => {
    const x = 0.5 + i * (stepW + arrowW);
    const highlight = i === 3;
    s.addText(step, {
      shape: pres.ShapeType.roundRect, rectRadius: 0.08, x, y: 2.88, w: stepW, h: 0.62,
      fontSize: 13, bold: highlight, align: "center", valign: "middle", margin: 2,
      color: highlight ? C.background1 : C.text1,
      fill: { color: highlight ? C.accent1 : C.accent5 }, objectName: `Step ${i + 1}`,
    });
    if (i < steps.length - 1) {
      s.addShape(pres.ShapeType.rightArrow, { x: x + stepW + 0.055, y: 3.1, w: 0.2, h: 0.18, fill: { color: C.accent4 }, line: { type: "none" }, objectName: `Arrow ${i + 1}` });
    }
  });

  // Done and not done
  const column = (x, heading, mark, color, tint, items, name) => {
    const w = 6.07, y = 3.68, h = 2.8;
    s.addShape(pres.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.06, fill: { color: tint }, line: { type: "none" }, objectName: `${name} panel` });
    s.addText(mark, { shape: pres.ShapeType.ellipse, x: x + 0.18, y: y + 0.12, w: 0.34, h: 0.34, fontSize: 14, bold: true, align: "center", valign: "middle", margin: 0, color: C.background1, fill: { color }, objectName: `${name} icon` });
    s.addText(heading, { x: x + 0.62, y: y + 0.1, w: w - 0.8, h: 0.38, fontSize: 18, bold: true, fontFace: "Cambria", color, margin: 0, valign: "middle", isTextBox: true, objectName: `${name} heading` });
    s.addText(items.map((text, i) => ({ text, options: { bullet: { indent: 13 }, breakLine: i < items.length - 1, paraSpaceAfter: 4 } })), {
      x: x + 0.18, y: y + 0.54, w: w - 0.36, h: h - 0.62, fontSize: 14, color: C.text1, margin: 0, valign: "top", isTextBox: true, objectName: `${name} list`,
    });
  };

  column(0.5, "Implemented and tested", "✓", C.accent1, C.background2, [
    "Live quote, 4 years of financials, latest 10-K and newer 10-Q",
    "Filing summaries with a code-checked quote for every point",
    "Follow-up agent with 3 tools, tested on both LLMs",
    "Automatic, labeled fallback seen working in a real Gemini overload",
    "React and FastAPI app with live progress; keys stay on the server",
    "Clear messages for ETFs, foreign filers and bad tickers",
  ], "Implemented");

  column(6.76, "Not done, or not yet proven", "!", C.accent2, C.accent3, [
    "Whether each summary is a fair reading of its quote isn't measured",
    "Follow-up answers aren't quote-checked, so a wrong year could slip by",
    "Latest Groq rate-limit fix is unit-tested, not yet proven live",
    "Cut for time: trend chart, tabs, source drawer, UI tests",
    "Not covered: foreign filers (20-F) and funds",
    "Free LLM tiers overload; Yahoo is unofficial; Portkey isn't connected",
  ], "Not done");

  // Path to production and caveat
  s.addText([
    { text: "Path to production: ", options: { bold: true, color: C.text2 } },
    { text: "licensed market data, paid LLM tier or gateway, human-reviewed evals, compliance review, SSO and audit logs, then an advisor pilot.", options: { color: C.text1 } },
  ], { x: 0.5, y: 6.56, w: 12.33, h: 0.3, fontSize: 14, margin: 0, valign: "middle", isTextBox: true, objectName: "Path to production" });

  s.addText("Small sample, mostly one run per company and LLM, on companies also used to tune the prompt. One unseen company (Disney) verified 19 of 19. Information only, not investment advice.", {
    x: 0.5, y: 6.88, w: 12.33, h: 0.26, fontSize: 11, color: C.accent4, margin: 0, valign: "middle", isTextBox: true, objectName: "Sample note",
  });

  s.addNotes(`TALK TRACK (about 2 minutes)

Problem: advisors spend time gathering facts before they can advise. This turns a ticker into a one-page briefing they can check.

Key design choice: the briefing is a fixed pipeline, so every advisor gets the same steps. The agent is only for follow-up questions, which are unpredictable. Figures come straight from the data sources and are never written by the LLM.

Trust: every summary point carries a quote, and code checks that the quote is in the filing and contains the point's amounts. Flagged points stay visible rather than being hidden.

Be upfront: 95% means the quote exists and contains the amounts. It doesn't prove the summary is a fair reading, so advisors still see the quote. The sample is small, and the prompt was tuned on these companies. Disney, not used for tuning, verified 19 of 19, but that's one company.

Story worth telling: a real run put correct revenue figures against the wrong years on Groq while my check still passed. I caught it by reading the answer, restructured the tool data, added a flag for figures not in the sources, and made the check fail on that error. Also, rounding table values took Walmart down to 53%; a prompt change took it to 100% without loosening the check.

Tradeoffs: React over a quick Python UI, so keys stay on the server and the backend can serve other clients. Cost: tighter time, so the chart, tabs and frontend tests were cut. Own Gemini and Groq keys were used rather than the provided Portkey gateway; a gateway would be the production answer for keys, routing and logging.

Measured cost driver: a median of about 30,000 input and 1,700 output tokens per full briefing.`);

  const out = process.argv[2];
  await pres.writeFile({ fileName: out });
  await applyTheme(out, THEME);
  console.log("wrote", path.basename(out));
})();

